  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_2 : Integer;
    in attribute io_2_valid : Boolean;
    attribute measuredCm_i32 : Integer := 0;
    attribute targetCm_i32 : Integer := 0;
    attribute comparisonResultCode_i32 : Integer := 0;
    perform action tick {
      first start;
      then if io_1 {
        first start;
        then assign measuredCm_i32 := (if io_0 < 0.0 ? 0 else (if io_0 > 20000.0 ? 20000 else RealFunctions::floor(io_0)));
      }
      then if io_2_valid {
        first start;
        then assign targetCm_i32 := (if io_2 < 0 ? 0 else (if io_2 > 20000 ? 20000 else io_2));
      }
      then assign comparisonResultCode_i32 := (if measuredCm_i32 > targetCm_i32 ? 0 else (if measuredCm_i32 == targetCm_i32 ? 1 else 2));
    }
    out attribute io_3 : Boolean = true;
    out attribute serial_0_trigger : Boolean = ((io_1) and (io_2_valid));
    out attribute serial_0_value_0 : Integer = measuredCm_i32;
    out attribute serial_0_value_1 : Integer = targetCm_i32;
    out attribute serial_0_value_2 : Integer = comparisonResultCode_i32;
  }
  part system : Controller;
}
